INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','determiners-quantifiers','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"determiners-quantifiers","title":"Determiners: some, any, each, all and neither","level":"A2","order":16,"summary":"Choose quantity and reference words from number, meaning and the type of noun phrase.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Some and any","Every and each","Both, either and neither","All, most and of"],"rules":[{"title":"Some and any","explanation":"Some is common in positive statements; any is common in negatives and open questions. Some is also natural in offers and requests when a positive response is anticipated. Any can mean it does not matter which in positive clauses.","pattern":"Would you like **some** tea? / Choose **any** seat.","commonMistakes":["Some and any are not fixed positive/negative opposites in every context."],"examples":["“Every book in this picture **has** a label.”","“Every box in this picture **has** a label.”"],"skill":"form"},{"title":"Every and each","explanation":"Every and each usually take a singular count noun and singular agreement. Every views the members as a complete group; each foregrounds them individually. Each of takes a plural noun phrase but the head each remains singular.","pattern":"**Every student has** a book. / **Each of the students has** one.","commonMistakes":["Every students mixes a singular determiner pattern with a plural noun."],"examples":["“Both books shown here **are** clearly labelled.”","“Both boxes shown here **are** clearly labelled.”"],"skill":"meaning"},{"title":"Both, either and neither","explanation":"Both refers to two together. Either selects one of two or leaves either choice open. Neither excludes both. Before a noun, either and neither usually take a singular count form; both takes plural. Usage after neither of can vary, especially informally.","pattern":"**Both seats are** free. / **Neither seat is** free.","commonMistakes":["Do not add not to neither merely to express the same negative meaning."],"examples":["“Most **of** the books in the picture are labelled.”","“Most **of** the boxes in the picture are labelled.”"],"skill":"contrast"},{"title":"All, most and of","explanation":"Use all or most directly before a general plural noun. Before a determiner or object pronoun, use an of-pattern where required: most of the books, all of them. All can often omit of before the: all the books.","pattern":"**Most books** / **Most of the books** / **All of them**","commonMistakes":["Most the books is missing of. Avoid assuming all and most have identical rules in every pattern."],"examples":["Exactly two books were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**","Exactly two boxes were considered, and neither was selected. What does “neither” mean here? → **Not one and not the other.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"9a9a6108-cf32-578a-ade4-b2153698a1ed","topicSlug":"determiners-quantifiers","level":"A2","prompt":"“Every book in this picture ____ a label.”","choices":[{"id":"A","text":"having"},{"id":"B","text":"to have"},{"id":"C","text":"has"},{"id":"D","text":"have"}],"answerId":"C","hint":"Every presents the members one at a time: use **singular agreement**.","explanation":"**Every book** is singular, so its verb is **has**.","keywords":["every-singular-agreement"],"skill":"every-singular-agreement","contextKey":"determiners-quantifiers-1","fingerprint":"ad39a69cc84b6d8dbe2307c3f3bf12612d22c180fdea983b1dfe24b85bbac2a1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Every presents the members one at a time: use **singular agreement**.","**Every book** is singular, so its verb is **has**.","Choose **has**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Having alone is not a finite verb.","B":"A to-infinitive cannot be the finite predicate.","C":"**Every book** is singular, so its verb is **has**.","D":"Every takes singular agreement in this pattern."}}},{"id":"0f2d825a-8729-556b-a95f-43a1a9181ec4","topicSlug":"determiners-quantifiers","level":"A2","prompt":"“Both books shown here ____ clearly labelled.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"are"},{"id":"C","text":"is"},{"id":"D","text":"am"}],"answerId":"B","hint":"Both means **the two together**.","explanation":"**Both** selects two things and takes plural agreement.","keywords":["both-plural-agreement"],"skill":"both-plural-agreement","contextKey":"determiners-quantifiers-1","fingerprint":"e506959ce4e68bbe4196b41936c2f0b70070c06af306a0f780f7a0d33976a7e6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Both means **the two together**.","**Both** selects two things and takes plural agreement.","Choose **are**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not a finite present form here.","B":"**Both** selects two things and takes plural agreement.","C":"Is is singular; both refers to two.","D":"Am agrees only with I."}}},{"id":"9144d99b-4a3a-527d-ab50-2eebe751fd71","topicSlug":"determiners-quantifiers","level":"A2","prompt":"“Most ____ the books in the picture are labelled.”","choices":[{"id":"A","text":"to"},{"id":"B","text":"than"},{"id":"C","text":"of"},{"id":"D","text":"—"}],"answerId":"C","hint":"There is already a determiner **the**, so use **most of the**.","explanation":"Before **the + noun**, most uses **of**.","keywords":["most-of-determined"],"skill":"most-of-determined","contextKey":"determiners-quantifiers-1","fingerprint":"36d6873812f63801d54daab2d23b70500a7b138fd07bf4dff3c99965d025c9c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["There is already a determiner **the**, so use **most of the**.","Before **the + noun**, most uses **of**.","Choose **of**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To does not form this partitive pattern.","B":"Than is used in comparisons, not after most in this quantity phrase.","C":"Before **the + noun**, most uses **of**.","D":"Most the ... omits the required of."}}},{"id":"1a491eba-58e1-522d-ab58-36a944ea4e93","topicSlug":"determiners-quantifiers","level":"A2","prompt":"Exactly two books were considered, and neither was selected. What does “neither” mean here?","choices":[{"id":"A","text":"One was selected, but we do not know which."},{"id":"B","text":"All but one were selected."},{"id":"C","text":"Not one and not the other."},{"id":"D","text":"Both were selected."}],"answerId":"C","hint":"The context names **two choices** and excludes each of them.","explanation":"**Neither** excludes both members of the stated pair.","keywords":["neither-meaning"],"skill":"neither-meaning","contextKey":"determiners-quantifiers-1","fingerprint":"ee27d9efb4e503171577ae4360363fa041f8bd8141822068ddccce5fcdd1e378","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The context names **two choices** and excludes each of them.","**Neither** excludes both members of the stated pair.","Choose **Not one and not the other.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would leave one selected; neither excludes both.","B":"With two items, that would select one, contradicting neither.","C":"**Neither** excludes both members of the stated pair.","D":"That is the opposite of neither."}}},{"id":"c7be6873-db05-5c5c-ad38-d2e5def7c050","topicSlug":"determiners-quantifiers","level":"A2","prompt":"“Every box in this picture ____ a label.”","choices":[{"id":"A","text":"to have"},{"id":"B","text":"has"},{"id":"C","text":"have"},{"id":"D","text":"having"}],"answerId":"B","hint":"Every presents the members one at a time: use **singular agreement**.","explanation":"**Every box** is singular, so its verb is **has**.","keywords":["every-singular-agreement"],"skill":"every-singular-agreement","contextKey":"determiners-quantifiers-2","fingerprint":"a11802b4ce466f23422f34064827b76f83f81969f5b1d33b3231967fc226f2de","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Every presents the members one at a time: use **singular agreement**.","**Every box** is singular, so its verb is **has**.","Choose **has**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive cannot be the finite predicate.","B":"**Every box** is singular, so its verb is **has**.","C":"Every takes singular agreement in this pattern.","D":"Having alone is not a finite verb."}}},{"id":"60588219-07fb-5964-ab12-55e544c624ef","topicSlug":"determiners-quantifiers","level":"A2","prompt":"“Both boxes shown here ____ clearly labelled.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"are"},{"i